import { useEffect, useRef, useState, type ReactNode } from 'react';
import kontenLogo from './assets/konten-logo.png';
import { InstallAppPanel, PwaUpdateNotice, useInstallApp } from './components/InstallApp';
import { ExchangeRatesPanel, useExchangeRates } from './components/ExchangeRates';
import { DataBackupPanel } from './components/DataBackup';
import { CloudAccountPanel, CloudSyncNotice } from './components/CloudAccount';
import { useCloudSync } from './hooks/useCloudSync';
import { restoreBackupRateCaches } from './lib/backup';
import { ArrowDown, ArrowDownLeft, ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, CalendarDays, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Coffee, Download, Ellipsis, FileBarChart2, FileSpreadsheet, FileText, GraduationCap, House, LayoutDashboard, Menu, MoreHorizontal, Pencil, PiggyBank, Plus, Search, Settings2, ShieldCheck, ShoppingBag, SlidersHorizontal, Sparkles, Target, Trash2, TrendingUp, Wallet, X, BriefcaseBusiness, Car, Heart, Plane, Utensils, CircleDollarSign, ArrowLeftRight, ChartNoAxesCombined, ChartPie, ChartColumnIncreasing } from 'lucide-react';
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Scatter, ScatterChart, Tooltip, XAxis, YAxis } from 'recharts';
import { calculateSummary, categoryTotals, monthlyTrend, initialData, categories, categoryColors, frequencyLabels, incomeInMonth, expenseInMonth, entryCurrency, resolveEntryRate, type ConversionContext, type FinanceData, type Income, type Expense, type SavingsGoal } from './lib/finance';
import { currencies, currencyLabels, convertAmount, isCurrency, isValidRateSnapshot, roundCurrency, type Currency, type CurrencyRateSnapshot, type RateType } from './lib/currency';

type Page = 'overview' | 'transactions' | 'budget' | 'goals' | 'reports';
type ChartType = 'pie' | 'bar' | 'scatter';
type ModalState = { type: 'movement'; kind: 'income' | 'expense'; item?: Income | Expense; fixed?: boolean } | { type: 'goal'; item?: SavingsGoal } | { type: 'customize' } | { type: 'settings' } | { type: 'help' } | null;
// Keep the existing storage keys so a branding change preserves personal records.
const STORAGE_KEY = 'balance-finance-v1';
const PREF_KEY = 'balance-preferences-v1';
const today = new Date().toLocaleDateString('en-CA');
const currentMonth = today.slice(0, 7);
const pageNames: Record<Page, string> = { overview: 'Resumen general', transactions: 'Movimientos', budget: 'Mi presupuesto', goals: 'Metas de ahorro', reports: 'Informes y exportaciones' };
const catIcons: Record<string, typeof House> = { Vivienda: House, Alimentación: Utensils, Transporte: Car, Educación: GraduationCap, Ocio: Coffee, Viajes: Plane, Trabajo: BriefcaseBusiness, Salud: Heart, Otros: ShoppingBag };
type Preferences = { currency: Currency; rateType: RateType; chart: ChartType; cards: string[]; showTransactions: boolean; showGoals: boolean; demo: boolean };
// Older releases offered MXN as a display label without converting amounts.
// Preserve those records until the owner confirms their actual source currency.
type AppData = FinanceData & { legacyCurrencyReview?: string };
const defaultPrefs: Preferences = { currency: 'USD', rateType: 'sell', chart: 'pie', cards: ['income', 'fixed', 'savings', 'available'], showTransactions: true, showGoals: true, demo: true };
function readSavedPrefs(): Record<string, unknown> { try { const value = JSON.parse(localStorage.getItem(PREF_KEY) || '{}'); return value && typeof value === 'object' ? value : {}; } catch { return {}; } }
function migrateCurrency(data: AppData, original: Currency): AppData {
  return { ...data, legacyCurrency: original,
    incomes: data.incomes.map(item => ({ ...item, currency: isCurrency(item.currency) ? item.currency : original })),
    expenses: data.expenses.map(item => ({ ...item, currency: isCurrency(item.currency) ? item.currency : original })),
    goals: data.goals.map(item => ({ ...item, currency: isCurrency(item.currency) ? item.currency : original })),
    savingsCurrency: isCurrency(data.savingsCurrency) ? data.savingsCurrency : original,
  };
}
function loadData(): AppData {
  try {
    const data = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null') as AppData | null;
    if (data && Array.isArray(data.incomes) && Array.isArray(data.expenses) && Array.isArray(data.goals) && typeof data.savingsAmount === 'number') {
      if (data.legacyCurrencyReview) return data;
      const previous = readSavedPrefs().currency;
      if (!isCurrency(data.legacyCurrency) && typeof previous === 'string' && !isCurrency(previous)) return { ...data, legacyCurrencyReview: previous };
      return migrateCurrency(data, isCurrency(data.legacyCurrency) ? data.legacyCurrency : isCurrency(previous) ? previous : 'USD');
    }
  } catch {}
  return migrateCurrency(structuredClone(initialData), 'USD');
}
function loadPrefs(): Preferences {
  const saved = readSavedPrefs();
  return { ...defaultPrefs, ...saved,
    currency: isCurrency(saved.currency) ? saved.currency : 'USD',
    rateType: saved.rateType === 'buy' ? 'buy' : 'sell',
    chart: saved.chart === 'bar' || saved.chart === 'scatter' ? saved.chart : 'pie',
    cards: Array.isArray(saved.cards) ? saved.cards.filter((card): card is string => typeof card === 'string' && defaultPrefs.cards.includes(card)) : [...defaultPrefs.cards],
  };
}
function snapshotCopy(snapshot: unknown): CurrencyRateSnapshot | undefined { return isValidRateSnapshot(snapshot) ? structuredClone(snapshot) : undefined; }
function money(amount: number | null, code: string): string {
  if (amount === null || !Number.isFinite(amount)) return 'Sin tasa';
  try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: code, currencyDisplay: 'narrowSymbol', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(roundCurrency(amount)); } catch { return `${roundCurrency(amount).toFixed(2)} ${code}`; }
}
function rateDescription(snapshot: CurrencyRateSnapshot | null | undefined): string {
  if (!isValidRateSnapshot(snapshot)) return 'Sin referencia de cambio';
  const date = new Date(`${snapshot.date}T12:00:00`).toLocaleDateString('es-NI');
  return `${snapshot.provider === 'BAC' ? 'BAC' : 'Manual'} · ${snapshot.rateType === 'sell' ? 'venta' : 'compra'} · ${snapshot.dateKind === 'observed' || snapshot.provider === 'BAC' && snapshot.dateKind !== 'effective' ? 'consultada el' : 'fecha efectiva'} ${date}`;
}
function CurrencyOptions({ compact = false }: { compact?: boolean }) { const shortNames = { USD: 'Dólar', NIO: 'Córdoba', EUR: 'Euro' }; return <>{currencies.map(code => <option value={code} key={code}>{compact ? `${code} · ${shortNames[code]}` : `${currencyLabels[code]} (${code})`}</option>)}</>; }
function monthLabel(month: string) { return new Date(`${month}-15T12:00:00`).toLocaleDateString('es', { month: 'long', year: 'numeric' }); }
function IconCategory({ category, small = false }: { category: string; small?: boolean }) { const Icon = catIcons[category] || CircleDollarSign; return <span className={`category-icon ${small ? 'small' : ''}`} style={{ background: `${categoryColors[category] || '#8aa99b'}22`, color: categoryColors[category] || '#527666' }}><Icon size={small ? 15 : 19} strokeWidth={1.7} /></span>; }
function App() {
  const installApp = useInstallApp();
  const [data, setData] = useState<AppData>(loadData);
  const [prefs, setPrefs] = useState(loadPrefs);
  const exchangeRates = useExchangeRates(prefs.rateType);
  const [page, setPage] = useState<Page>('overview');
  const [month, setMonth] = useState(currentMonth);
  const [modal, setModal] = useState<ModalState>(null);
  const [toast, setToast] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [exportOpen, setExportOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('all');
  const [chartFilter, setChartFilter] = useState('all');
  const [busy, setBusy] = useState(false);
  const [storageError, setStorageError] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);
  const cloud = useCloudSync({ data, preferences: prefs,
    onDocument: document => { setData(document.data); setPrefs({ ...defaultPrefs, ...document.preferences, demo: false }); },
    onLocal: () => { setData(loadData()); setPrefs(loadPrefs()); setModal(current => current?.type === 'settings' ? current : null); },
    deferSync: Boolean(modal && modal.type !== 'settings'),
  });
  const accountGate = cloud.phase === 'loading' || Boolean(cloud.email && !cloud.isCloud) || cloud.readOnly;
  const usesLocalStorage = !cloud.email && !cloud.isCloud && cloud.phase !== 'loading';
  useEffect(() => { if (!usesLocalStorage) return; try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); setStorageError(false); } catch { setStorageError(true); } }, [data, usesLocalStorage]);
  useEffect(() => { if (!usesLocalStorage) return; try { localStorage.setItem(PREF_KEY, JSON.stringify(prefs)); } catch { setStorageError(true); } }, [prefs, usesLocalStorage]);
  useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timer); } }, [toast]);
  useEffect(() => { function key(e: KeyboardEvent) { if (e.key === 'Escape') { setModal(null); setExportOpen(false); setNotificationsOpen(false); setSidebarOpen(false); } } window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, []);
  const conversion: ConversionContext = { currency: prefs.currency, rates: exchangeRates.snapshot };
  const summary = data.legacyCurrencyReview ? { income: null, fixedExpenses: null, variableExpenses: null, savings: null, freeBudget: null, available: null, savingsRate: null, complete: false, missingConversions: [] } : calculateSummary(data, month, conversion);
  const currency = (amount: number | null) => money(amount, prefs.currency);
  const tooltipMoney = (value: unknown) => currency(value === null || value === undefined ? null : Number(value));
  const shortMoney = (amount: number | null, code = prefs.currency as string) => money(amount, code).replace('.00', '');
  const originalCurrency = (entry: Income | Expense | SavingsGoal) => isCurrency(entry.currency) ? entry.currency : data.legacyCurrencyReview || entryCurrency(entry, data);
  const chartData = chartFilter === 'fixed' ? { ...data, expenses: data.expenses.filter(e => e.kind === 'fixed') } : data;
  const chartConversionMissing = Boolean(data.legacyCurrencyReview) || chartData.expenses.some(e => expenseInMonth(e, month) > 0 && expenseInMonth(e, month, conversion) === null);
  const totals = data.legacyCurrencyReview ? [] : categoryTotals(chartData, month, conversion);
  const chartTotal = totals.reduce((sum, c) => sum + c.value, 0);
  const trend = monthlyTrend(data, month, 6, conversion).map(point => data.legacyCurrencyReview ? { ...point, income: null, expenses: null, savings: null, available: null } : point);
  const fixedRows = data.expenses.filter(e => e.kind === 'fixed' && expenseInMonth(e, month) > 0);
  const incomeRows = data.incomes.filter(i => incomeInMonth(i, month) > 0);
  const expenseRows = data.expenses.filter(e => expenseInMonth(e, month) > 0);
  function originalMonthlyAmount(m: Income | Expense) { return 'kind' in m ? expenseInMonth(m, month) : incomeInMonth(m, month); }
  function monthlyAmount(m: Income | Expense) { return data.legacyCurrencyReview && !isCurrency(m.currency) ? null : 'kind' in m ? expenseInMonth(m, month, conversion) : incomeInMonth(m, month, conversion); }
  const goalSavedTotal = data.legacyCurrencyReview ? null : data.goals.reduce<number | null>((sum, goal) => { const value = convertAmount(goal.saved, entryCurrency(goal, data), prefs.currency, resolveEntryRate(goal, conversion)); return sum === null || value === null ? null : sum + value; }, 0);
  const savingsCurrency = isCurrency(data.savingsCurrency) ? data.savingsCurrency : data.legacyCurrencyReview || data.legacyCurrency || 'USD';
  function editMovement(kind: 'income' | 'expense', item: Income | Expense) {
    if (data.legacyCurrencyReview && !isCurrency(item.currency)) { setModal({ type: 'settings' }); setToast('Confirma primero la moneda original de tus registros anteriores.'); return; }
    setModal({ type: 'movement', kind, item });
  }
  function editGoal(item: SavingsGoal) {
    if (data.legacyCurrencyReview && !isCurrency(item.currency)) { setModal({ type: 'settings' }); setToast('Confirma primero la moneda original de tus metas anteriores.'); return; }
    setModal({ type: 'goal', item });
  }
  function recurrence(m: Income | Expense) { return ('kind' in m && m.kind === 'variable') ? 'once' : m.frequency || 'monthly'; }
  function displayDate(m: Income | Expense) { return recurrence(m) === 'once' ? m.date : `${month}-${m.date.slice(8, 10)}`; }
  const movements = [...incomeRows.map(i => ({ ...i, direction: 'income' as const })), ...expenseRows.map(e => ({ ...e, direction: 'expense' as const }))].sort((a, b) => displayDate(b).localeCompare(displayDate(a)));
  const filteredMovements = movements.filter(m => (filter === 'all' || (filter === 'income' ? m.direction === 'income' : filter === 'fixed' ? m.direction === 'expense' && 'kind' in m && m.kind === 'fixed' : filter === 'variable' ? m.direction === 'expense' && 'kind' in m && m.kind === 'variable' : m.direction === 'expense')) && `${m.name} ${m.category}`.toLowerCase().includes(query.toLowerCase()));
  function navigate(next: Page) { setPage(next); setSidebarOpen(false); setQuery(''); setFilter('all'); }
  function shiftMonth(delta: number) { const d = new Date(`${month}-15T12:00:00`); d.setMonth(d.getMonth() + delta); setMonth(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`); }
  function updatePrefs(patch: Partial<Preferences>) { setPrefs(p => ({ ...p, ...patch })); }
  const reportRows = movements.map(m => {
    const converted = monthlyAmount(m);
    const snapshot = resolveEntryRate(m, conversion);
    return { Concepto: m.name, Tipo: m.direction === 'income' ? 'Ingreso' : 'Gasto', Categoría: m.category, 'Fecha de inicio o compra': m.date,
      Periodicidad: m.direction === 'income' ? frequencyLabels[(m as Income).frequency] : (m as Expense).kind === 'fixed' ? frequencyLabels[(m as Expense).frequency || 'monthly'] : 'Puntual',
      'Importe por pago': m.direction === 'income' ? m.amount : -m.amount, 'Moneda original': originalCurrency(m),
      'Total original del mes': m.direction === 'income' ? originalMonthlyAmount(m) : -originalMonthlyAmount(m),
      'Total del mes': converted === null ? 'Sin tasa' : roundCurrency(m.direction === 'income' ? converted : -converted), 'Moneda del resumen': prefs.currency,
      'Fuente del cambio': data.legacyCurrencyReview && !isCurrency(m.currency) ? 'Pendiente de revisar moneda' : snapshot?.provider === 'BAC' ? 'BAC' : snapshot ? 'Manual' : originalCurrency(m) === prefs.currency ? 'Misma moneda' : 'Pendiente',
      'Referencia del cambio': snapshot ? snapshot.rateType === 'sell' ? 'Venta' : 'Compra' : '', 'Fecha del cambio': snapshot?.date || '',
      'Tipo de fecha del cambio': snapshot ? snapshot.dateKind === 'observed' || snapshot.provider === 'BAC' && snapshot.dateKind !== 'effective' ? 'Consulta' : 'Efectiva' : '',
      'Córdobas por USD': snapshot?.usd ?? '', 'Córdobas por EUR': snapshot?.eur ?? '',
    };
  });
  const compactReportRows = movements.map(m => ({ Concepto: m.name, Tipo: m.direction === 'income' ? 'Ingreso' : 'Gasto', Categoría: m.category,
    Periodicidad: frequencyLabels[recurrence(m)],
    'Original mensual': `${m.direction === 'income' ? '+' : '-'}${money(originalMonthlyAmount(m), originalCurrency(m))} ${originalCurrency(m)}`,
    [`Equivalente ${prefs.currency}`]: monthlyAmount(m) === null ? 'Sin tasa' : `${m.direction === 'income' ? '+' : '-'}${currency(monthlyAmount(m))}`,
  }));
  async function download(format: 'csv' | 'xlsx' | 'pdf' | 'docx' | 'png') {
    setExportOpen(false); setBusy(true);
    try {
      if ((format === 'pdf' || format === 'docx') && !summary.complete) { setToast(data.legacyCurrencyReview ? 'Confirma la moneda original en Ajustes antes de generar el informe.' : 'Configura el tipo de cambio en Ajustes para completar el resumen antes de exportar PDF o Word.'); return; }
      const { exportTable, exportReport, exportDashboard } = await import('./lib/exports');
      if ((format === 'csv' || format === 'xlsx') && !reportRows.length) { setToast('Añade un movimiento este mes para exportar la tabla.'); return; }
      if (format === 'png') { if (dashboardRef.current) await exportDashboard(dashboardRef.current); }
      else if (format === 'csv' || format === 'xlsx') exportTable(reportRows, format, `konten-${month}`);
      else await exportReport({ title: 'KONTEN · Tu resumen financiero', period: monthLabel(month), summary: { 'Moneda del resumen': prefs.currency, Ingresos: currency(summary.income), 'Gastos fijos': currency(summary.fixedExpenses), 'Gastos variables': currency(summary.variableExpenses), 'Ahorro reservado': currency(summary.savings), Disponible: currency(summary.available), 'Referencia actual': rateDescription(exchangeRates.snapshot), 'Criterio de conversión': 'Cada registro conserva su tasa guardada; los registros sin tasa usan la referencia actual.' }, rows: compactReportRows }, format);
      setToast('Tu archivo está listo. Revisa las descargas.');
    } catch { setToast('No pudimos generar el archivo. Vuelve a intentarlo.'); } finally { setBusy(false); }
  }
  function removeMovement(item: typeof movements[number]) {
    if (!window.confirm(`¿Eliminar «${item.name}»? ${item.direction === 'income' && (item as Income).frequency !== 'once' || item.direction === 'expense' && (item as Expense).kind === 'fixed' ? 'Se eliminará la recurrencia de todos los meses desde su inicio.' : 'Esta acción no se puede deshacer.'}`)) return;
    setData(d => item.direction === 'income' ? { ...d, incomes: d.incomes.filter(i => i.id !== item.id) } : { ...d, expenses: d.expenses.filter(e => e.id !== item.id) }); setToast('Movimiento eliminado.');
  }
  function MovementTable({ compact = false }: { compact?: boolean }) {
    const rows = compact ? movements.slice(0, 4) : filteredMovements;
    return <div className="table-scroll"><table className="movement-table"><thead><tr><th>Concepto</th><th>Categoría</th><th>Fecha</th><th className="text-right">Monto mensual</th>{!compact && <th><span className="sr-only">Acciones</span></th>}</tr></thead><tbody>{rows.map(m => <tr key={`${m.direction}-${m.id}`}>
      <td><div className="concept"><IconCategory category={m.direction === 'income' ? 'Trabajo' : m.category} /><div><strong>{m.name}</strong><span>{recurrence(m) === 'biweekly' ? `Quincenal · 2 × ${money(m.amount, originalCurrency(m))} ${originalCurrency(m)}` : m.direction === 'income' ? frequencyLabels[(m as Income).frequency] : (m as Expense).kind === 'fixed' ? 'Gasto fijo · automático' : 'Gasto variable'}</span></div></div></td>
      <td><span className="category-tag">{m.category}</span></td><td className="muted date-cell">{recurrence(m) !== 'once' ? recurrence(m) === 'biweekly' ? 'Quincenal' : 'Mensual' : new Date(`${m.date}T12:00:00`).toLocaleDateString('es', { day: '2-digit', month: 'short' })}</td>
      <td className={`amount text-right ${m.direction === 'income' ? 'positive' : ''}`}><span>{m.direction === 'income' ? '+' : '−'}{money(originalMonthlyAmount(m), originalCurrency(m))} {originalCurrency(m)}</span><small className="movement-equivalent">{monthlyAmount(m) === null ? 'Sin tasa · equivalencia pendiente' : `≈ ${m.direction === 'income' ? '+' : '−'}${currency(monthlyAmount(m))} ${prefs.currency}`}</small></td>
      {!compact && <td><div className="row-actions"><button aria-label={`Editar ${m.name}`} onClick={() => editMovement(m.direction, m)}><Pencil size={15} /></button><button aria-label={`Eliminar ${m.name}`} onClick={() => removeMovement(m)}><Trash2 size={15} /></button></div></td>}</tr>)}</tbody></table>{rows.length === 0 && (movements.length > 0 && !compact ? <Empty icon={<Search size={26} />} title="No encontramos coincidencias" text="Prueba con otro concepto o vuelve a ver todos tus movimientos." action={() => { setQuery(''); setFilter('all'); }} label="Limpiar filtros" /> : <Empty icon={<ArrowLeftRight size={26} />} title="Aquí comienza tu historia" text="Añade un ingreso o gasto para ver tus movimientos de este mes." action={() => setModal({ type: 'movement', kind: 'expense' })} label="Crear movimiento" />)}</div>;
  }
  function GoalsPanel({ full = false }: { full?: boolean }) {
    return <div className={full ? 'goals-grid' : 'goal-items'}>{data.goals.map((g, i) => <div className={`goal-item ${full ? 'panel goal-full' : ''}`} key={g.id}><div className="goal-top"><span className={`goal-illustration ${i % 2 ? 'sage' : ''}`}>{i % 2 ? <ShieldCheck size={21} /> : <Plane size={21} />}</span><div><h3>{g.name}</h3><span>{Math.round(g.target > 0 ? g.saved / g.target * 100 : 0)}% de tu meta</span></div><button className="icon-button" aria-label={`Editar meta ${g.name}`} onClick={() => editGoal(g)}><MoreHorizontal size={19} /></button></div>
      <div className="goal-amount"><strong>{shortMoney(g.saved, originalCurrency(g))}</strong><span>de {shortMoney(g.target, originalCurrency(g))} {originalCurrency(g)}</span></div><div className="progress-track"><div style={{ width: `${g.target > 0 ? Math.min(100, g.saved / g.target * 100) : 0}%`, background: i % 2 ? '#087f46' : '#36a58b' }} /></div>{full && <div className="goal-details"><span>Aporte mensual sugerido</span><strong>{money(g.monthly, originalCurrency(g))} {originalCurrency(g)}</strong></div>}</div>)}{data.goals.length === 0 && <Empty icon={<Target size={25} />} title="Dale un propósito a tu ahorro" text="Crea tu primera meta y celebra cada avance." action={() => setModal({ type: 'goal' })} label="Crear una meta" />}</div>;
  }
  const stats = [
    { id: 'income', label: 'Ingresos del mes', value: summary.income, icon: Wallet, color: 'green', detail: `${incomeRows.length} ${incomeRows.length === 1 ? 'fuente de ingreso' : 'fuentes de ingreso'}`, tag: 'Este mes' },
    { id: 'fixed', label: 'Gastos fijos', value: summary.fixedExpenses, icon: ArrowDownToLine, color: 'orange', detail: 'Tus compromisos, contemplados', tag: 'Automáticos' },
    { id: 'savings', label: 'Ahorro reservado', value: summary.savings, icon: PiggyBank, color: 'purple', detail: summary.savingsRate === null ? 'Equivalencia pendiente' : `${Math.round(summary.savingsRate)}% de tus ingresos`, tag: 'Tu futuro' },
    { id: 'available', label: 'Disponible para ti', value: summary.available, icon: CircleDollarSign, color: 'accent', detail: 'Después de gastos y ahorro', tag: 'Libre de compromisos' },
  ];
  return <div className="app-shell">
    {sidebarOpen && <div className="sidebar-backdrop" onClick={() => setSidebarOpen(false)} />}
    <aside className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
      <a className="brand" href="#" onClick={e => { e.preventDefault(); navigate('overview'); }} aria-label="KONTEN, inicio"><img className="brand-logo" src={kontenLogo} alt="" width="44" height="44" />KONTEN<span className="brand-dot" aria-hidden="true">.</span></a>
      <button className="workspace-selector" onClick={() => setModal({ type: 'settings' })}><span className="workspace-avatar"><Wallet size={18} /></span><span><strong>Mis finanzas</strong><small>Espacio personal</small></span><ChevronDown size={15} /></button>
      <span className="nav-label">TU ESPACIO</span>
      <nav>{([['overview', LayoutDashboard, 'Resumen general'], ['transactions', ArrowLeftRight, 'Movimientos'], ['budget', Wallet, 'Mi presupuesto'], ['goals', Target, 'Metas de ahorro'], ['reports', FileBarChart2, 'Informes']] as const).map(([key, Icon, label]) => <button key={key} className={`nav-item ${page === key ? 'active' : ''}`} onClick={() => navigate(key)}><Icon size={19} strokeWidth={1.7} /><span>{label}</span>{page === key && <span className="nav-active-dot" />}</button>)}</nav>
      <div className="sidebar-bottom"><div className="sidebar-tip"><span className="tip-icon"><Sparkles size={18} /></span><h3>Un pequeño hábito.<br />Un gran cambio.</h3><p>Revisar tus finanzas hoy es cuidar de tu yo del futuro.</p><button onClick={() => navigate('goals')}>Dale forma a tu próxima meta <ArrowUpRight size={14} /></button></div><button className="nav-item secondary" onClick={() => setModal({ type: 'help' })}><CircleHelp size={19} strokeWidth={1.7} />Ayuda y consejos</button><button className="profile" onClick={() => setModal({ type: 'settings' })}><span className="avatar">TÚ</span><span><strong>Mi cuenta personal</strong><small>Todo está bajo control</small></span><Settings2 size={17} /></button></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="topbar-heading"><button className="icon-button mobile-menu" onClick={() => setSidebarOpen(true)} aria-label="Abrir menú"><Menu size={22} /></button><span className="breadcrumb">Mi espacio</span><ChevronRight size={12} /><strong>{pageNames[page]}</strong></div><div className="topbar-actions"><button className="local-badge cloud-status-trigger" onClick={() => setModal({ type: 'settings' })}><span />{cloud.phase === 'synced' ? 'Sincronizado con tu cuenta' : cloud.isCloud ? cloud.phase === 'offline' ? 'Sin conexión · cambios pendientes' : 'Cambios por sincronizar' : 'Guardado en este dispositivo'}</button>{prefs.demo && <button className="demo-badge" onClick={() => setModal({ type: 'settings' })}>Datos de ejemplo <ArrowUpRight size={11} /></button>}<div className="notification-wrap"><button className={`icon-button notification-button ${notificationsOpen ? 'selected' : ''}`} aria-label="Notificaciones" onClick={() => setNotificationsOpen(!notificationsOpen)}><Bell size={19} /><i /></button>{notificationsOpen && <div className="popover notifications"><h3>Un poco de tranquilidad <span className="notification-count">2</span></h3><div><ShieldCheck size={20} /><p><strong>{summary.complete ? 'Tus gastos fijos están incluidos' : 'Hay conversiones pendientes'}</strong><span>{summary.complete ? 'El disponible ya contempla tus compromisos del mes.' : 'Configura las tasas para completar el disponible.'}</span></p></div><div><PiggyBank size={20} /><p><strong>{summary.savings !== null && summary.savings > 0 ? 'Tu ahorro tiene su lugar' : 'Tu próxima meta te espera'}</strong><span>{summary.savings !== null && summary.savings > 0 ? `${currency(summary.savings)} reservados para tu futuro.` : 'Puedes reservar un monto desde Mi presupuesto.'}</span></p></div><button className="text-button" onClick={() => setNotificationsOpen(false)}>Entendido <CheckCheck size={15} /></button></div>}</div><span className="top-avatar">TÚ</span></div></header>
      {accountGate && <section className="cloud-account-gate" aria-label="Acceso a tus finanzas"><ShieldCheck size={32} /><h1>{cloud.readOnly ? 'Revisá tu cuenta para continuar' : cloud.phase === 'loading' ? 'Preparando tu cuenta…' : 'Elegí cómo continuar con tus finanzas'}</h1><p>{cloud.readOnly ? cloud.error || 'Hay cambios que requieren tu decisión antes de continuar.' : 'Abrí tu cuenta para continuar. Los registros locales de este dispositivo se conservan.'}</p><button className="primary-button" onClick={() => setModal({ type: 'settings' })}>Abrir mi cuenta</button></section>}
      <main ref={dashboardRef} className="main-content" hidden={accountGate}><div data-export-ignore="true"><PwaUpdateNotice state={installApp} /><CloudSyncNotice state={cloud} onOpen={() => setModal({ type: 'settings' })} /></div>
        {storageError && <div className="storage-warning">No se pudieron guardar los cambios en el dispositivo. Exporta tus datos antes de cerrar esta página.</div>}
        <section className="page-heading"><div><div className="eyebrow"><span /> TU DINERO, CON MÁS CLARIDAD</div><h1>{page === 'overview' ? <>Cada peso, con propósito<span>.</span></> : page === 'transactions' ? <>Los detalles hacen la diferencia<span>.</span></> : page === 'budget' ? <>Haz espacio para lo que importa<span>.</span></> : page === 'goals' ? <>Pequeños pasos. Grandes planes<span>.</span></> : <>Tus finanzas, en tus manos<span>.</span></>}</h1><p>{page === 'overview' ? 'Menos cuentas en tu cabeza. Más tranquilidad en tu día.' : page === 'transactions' ? 'Todos tus ingresos y gastos, en un solo lugar.' : page === 'budget' ? 'Primero tus compromisos, después tus posibilidades.' : page === 'goals' ? 'Convierte lo que sueñas en algo que puedes alcanzar.' : 'Una perspectiva clara para tomar tu próxima decisión.'}</p></div><button className="primary-button" onClick={() => setModal({ type: page === 'goals' ? 'goal' : 'movement', kind: 'expense' } as ModalState)}><Plus size={17} />{page === 'goals' ? 'Nueva meta' : 'Nuevo movimiento'}</button></section>
        <div className="dashboard-toolbar"><div className="period-control"><span className="calendar-icon"><CalendarDays size={17} /></span><label className="month-label"><span>{monthLabel(month)}</span><input type="month" aria-label="Mes del resumen" value={month} onChange={e => e.target.value && setMonth(e.target.value)} /></label><span className="period-divider" /><button aria-label="Mes anterior" onClick={() => shiftMonth(-1)}><ChevronLeft size={16} /></button><button aria-label="Mes siguiente" onClick={() => shiftMonth(1)}><ChevronRight size={16} /></button></div><div className="toolbar-right"><label className="summary-currency">Moneda del resumen<select value={prefs.currency} onChange={e => isCurrency(e.target.value) && updatePrefs({ currency: e.target.value })}><CurrencyOptions compact /></select></label>{page === 'overview' && <button className="subtle-button" onClick={() => setModal({ type: 'customize' })}><SlidersHorizontal size={15} /><span>Personalizar vista</span></button>}<div className="export-wrap"><button className="outline-button" disabled={busy} onClick={() => setExportOpen(!exportOpen)}><Download size={15} />{busy ? 'Generando…' : 'Exportar'}<ChevronDown size={13} /></button>{exportOpen && <><div className="click-away" onClick={() => setExportOpen(false)} /><div className="popover export-menu"><span className="menu-heading">LLEVA TUS NÚMEROS CONTIGO</span><button onClick={() => download('xlsx')}><FileSpreadsheet size={17} /><span>Hoja de cálculo<small>Excel · .xlsx</small></span></button><button onClick={() => download('csv')}><FileText size={17} /><span>Tabla de movimientos<small>CSV · .csv</small></span></button><button onClick={() => download('pdf')}><FileBarChart2 size={17} /><span>Informe financiero<small>PDF · .pdf</small></span></button><button onClick={() => download('docx')}><FileText size={17} /><span>Informe editable<small>Word · .docx</small></span></button><button onClick={() => download('png')}><LayoutDashboard size={17} /><span>Captura de esta vista<small>Imagen · .png</small></span></button></div></>}</div></div></div>
        {data.legacyCurrencyReview && <div className="fx-warning" role="status"><span>Antes se mostraba {data.legacyCurrencyReview} como etiqueta, sin conversión. Confirma la moneda real de tus registros anteriores para calcular el resumen.</span><button className="text-button" onClick={() => setModal({ type: 'settings' })}>Revisar moneda original <ArrowRight size={14} /></button></div>}
        {!data.legacyCurrencyReview && !summary.complete && <div className="fx-warning" role="status"><span>Hay conversiones pendientes a {prefs.currency}: {summary.missingConversions.map(item => `${item.name} (${item.currency})`).join(', ')}. Los totales afectados muestran «Sin tasa».</span><button className="text-button" onClick={() => setModal({ type: 'settings' })}>Configurar tipo de cambio <ArrowRight size={14} /></button></div>}
        <div className="fx-summary-note"><span>Resumen en {prefs.currency}. Los movimientos conservan su moneda y tasa originales. {exchangeRates.snapshot ? rateDescription(exchangeRates.snapshot) : exchangeRates.loading ? 'Consultando BAC…' : 'Sin referencia actual para nuevas conversiones.'}</span><button className="text-button" onClick={() => setModal({ type: 'settings' })}>Tipo de cambio <ArrowRight size={13} /></button></div>
        {(page === 'overview' || page === 'budget') && <section className={`stats-grid cards-${page === 'budget' ? 4 : prefs.cards.length}`}>{(page === 'budget' ? stats : prefs.cards.map((id: string) => stats.find(s => s.id === id)).filter(Boolean) as typeof stats).map(s => <article className={`stat-card ${s.color}`} key={s.id}><div className="stat-top"><span>{s.label}</span><span className="stat-icon"><s.icon size={18} strokeWidth={1.7} /></span></div><div className="stat-value">{currency(s.value)}</div><div className="stat-bottom">{s.id === 'available' ? <span className="available-dot" /> : s.id === 'savings' ? <TrendingUp size={13} /> : <span className="stat-small-dot" />}<span>{s.detail}</span>{s.id === 'available' && <ArrowUpRight size={16} />}</div></article>)}</section>}
        {page === 'overview' && <><div className="overview-grid"><section className="panel spending-panel"><div className="panel-header"><div><h2>¿A dónde va tu dinero?</h2><p>Un vistazo a los gastos de tu mes.</p></div><select className="quiet-select" aria-label="Tipo de gastos de la gráfica" value={chartFilter} onChange={e => setChartFilter(e.target.value)}><option value="all">Todos los gastos</option><option value="fixed">Solo recurrentes</option></select></div><div className="chart-subnav"><span className="chart-currency">GASTOS POR CATEGORÍA</span><div className="chart-switch">{([['pie', ChartPie, 'Pastel'], ['bar', ChartColumnIncreasing, 'Barras'], ['scatter', ChartNoAxesCombined, 'Puntos']] as const).map(([type, Icon, title]) => <button key={type} title={title} aria-label={`Gráfica de ${title.toLowerCase()}`} aria-pressed={prefs.chart === type} className={prefs.chart === type ? 'active' : ''} onClick={() => updatePrefs({ chart: type })}><Icon size={15} /></button>)}</div></div>{totals.length ? <div className={`spending-chart-body ${prefs.chart !== 'pie' ? 'wide-chart' : ''}`}><div className="chart-container">{prefs.chart === 'pie' ? <><ResponsiveContainer width="100%" height="100%"><PieChart><Pie isAnimationActive={false} data={totals} dataKey="value" nameKey="name" innerRadius="72%" outerRadius="93%" paddingAngle={3} cornerRadius={4} stroke="none" startAngle={90} endAngle={-270}>{totals.map(c => <Cell fill={c.color} key={c.name} />)}</Pie><Tooltip formatter={tooltipMoney} contentStyle={tooltipStyle} /></PieChart></ResponsiveContainer><div className="donut-label"><span>Total de gastos</span><strong>{shortMoney(chartTotal)}</strong><small>{prefs.currency} · este mes</small></div></> : prefs.chart === 'bar' ? <ResponsiveContainer width="100%" height="100%"><BarChart data={totals} margin={{ left: -17, right: 6, bottom: 5 }}><CartesianGrid vertical={false} strokeDasharray="3 4" stroke="#dcebe2" /><XAxis dataKey="name" tick={{ fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip formatter={tooltipMoney} contentStyle={tooltipStyle} cursor={{ fill: '#f0f9f3' }} /><Bar isAnimationActive={false} dataKey="value" name="Gastos" radius={[5, 5, 0, 0]} maxBarSize={35}>{totals.map(c => <Cell fill={c.color} key={c.name} />)}</Bar></BarChart></ResponsiveContainer> : <ResponsiveContainer width="100%" height="100%"><ScatterChart margin={{ left: -17, right: 20, bottom: 5 }}><CartesianGrid strokeDasharray="3 4" stroke="#dcebe2" /><XAxis type="category" dataKey="name" name="Categoría" tick={{ fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis dataKey="value" name="Gasto" tick={{ fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip formatter={(v, name) => name === 'Gasto' ? tooltipMoney(v) : v} contentStyle={tooltipStyle} /><Scatter isAnimationActive={false} data={totals} fill="#14975b">{totals.map(c => <Cell key={c.name} fill={c.color} />)}</Scatter></ScatterChart></ResponsiveContainer>}</div><div className="chart-legend">{totals.slice(0, 6).map(c => <div key={c.name}><span className="legend-dot" style={{ background: c.color }} /><span>{c.name}</span><strong>{shortMoney(c.value)}</strong><small>{Math.round(c.value / chartTotal * 100)}%</small></div>)}{totals.length > 6 && <span className="more-categories">+ {totals.length - 6} categorías en la gráfica</span>}</div></div> : <Empty icon={<ChartPie size={25} />} title={chartConversionMissing ? 'Hay conversiones pendientes' : 'Tus números tomarán forma aquí'} text={chartConversionMissing ? 'Configura el tipo de cambio para mostrar todos los gastos en la misma moneda.' : 'Registra tu primer gasto para ver cómo se distribuye.'} action={() => setModal(chartConversionMissing ? { type: 'settings' } : { type: 'movement', kind: 'expense' })} label={chartConversionMissing ? 'Revisar conversiones' : 'Añadir gasto'} />}<div className="panel-footnote"><span className="soft-icon"><Sparkles size={13} /></span>{totals.length ? <span><strong>{totals[0].name}</strong> representa el {Math.round(totals[0].value / chartTotal * 100)}% de tus gastos de este mes.</span> : <span>Cada movimiento te ayuda a ver el panorama completo.</span>}</div></section>
        <section className="panel budget-panel"><div className="panel-header"><div><h2>Tu mes, en equilibrio</h2><p>Lo importante ya tiene su lugar.</p></div><span className="tiny-icon"><Wallet size={18} /></span></div><div className="budget-available"><span>De tus ingresos, puedes usar</span><strong>{currency(summary.available)}</strong><span className={`status-pill ${summary.available !== null && summary.available < 0 ? 'negative-pill' : ''}`}><span />{summary.available === null ? 'Completa las conversiones' : summary.available < 0 ? 'Revisa tus compromisos' : 'Vas por buen camino'}</span></div>{summary.complete && <div className="stacked-progress">{[{ v: summary.fixedExpenses, c: '#087f46' }, { v: summary.variableExpenses, c: '#8fcfa7' }, { v: summary.savings, c: '#3f9880' }, { v: Math.max(0, summary.available ?? 0), c: '#e5f1e9' }].map((s, i) => <span key={i} style={{ flex: s.v || 0.001, background: s.c }} />)}</div>}<div className="budget-breakdown">{[{ label: 'Gastos fijos', amount: summary.fixedExpenses, color: '#087f46' }, { label: 'Gastos variables', amount: summary.variableExpenses, color: '#8fcfa7' }, { label: 'Ahorro reservado', amount: summary.savings, color: '#3f9880' }].map(x => <div key={x.label}><span className="legend-dot" style={{ background: x.color }} /><span>{x.label}</span><strong>{shortMoney(x.amount)}</strong></div>)}</div><button className="panel-link" onClick={() => navigate('budget')}>Organizar mi presupuesto <ArrowRight size={15} /></button></section></div>
        <div className={`overview-bottom ${!prefs.showTransactions || !prefs.showGoals ? 'single-panel' : ''}`}>{prefs.showTransactions && <section className="panel transactions-panel"><div className="panel-header"><div><h2>Últimos movimientos</h2><p>Los pequeños detalles también cuentan.</p></div><button className="text-button" onClick={() => navigate('transactions')}>Ver todos <ArrowRight size={14} /></button></div><MovementTable compact /></section>}{prefs.showGoals && <section className="panel goals-panel"><div className="panel-header"><div><h2>Un paso más cerca</h2><p>Tus metas tienen un plan.</p></div><button className="icon-button" aria-label="Crear meta de ahorro" onClick={() => setModal({ type: 'goal' })}><Plus size={18} /></button></div><GoalsPanel /><button className="panel-link" onClick={() => navigate('goals')}>Ver mis metas <ArrowRight size={15} /></button></section>}</div></>}
        {page === 'transactions' && <section className="panel full-table"><div className="transactions-toolbar"><div className="filter-tabs">{[['all', 'Todos'], ['income', 'Ingresos'], ['fixed', 'Gastos fijos'], ['variable', 'Variables']].map(([value, label]) => <button className={filter === value ? 'active' : ''} key={value} onClick={() => setFilter(value)}>{label}</button>)}</div><label className="search-input"><Search size={16} /><input placeholder="Buscar movimiento…" value={query} onChange={e => setQuery(e.target.value)} /></label></div><MovementTable /><div className="table-footer"><span>{filteredMovements.length} movimientos · {monthLabel(month)}</span><span>Moneda: {prefs.currency}</span></div><div className="info-note"><CircleHelp size={16} />Los importes quincenales corresponden a cada quincena. El resumen mensual contempla dos pagos.</div></section>}
        {page === 'budget' && <div className="budget-page-grid"><section className="panel"><div className="panel-header"><div><h2>Primero, tus compromisos</h2><p>Se reservan automáticamente cada mes.</p></div><button className="outline-button" onClick={() => setModal({ type: 'movement', kind: 'expense', fixed: true })}><Plus size={15} />Añadir gasto fijo</button></div><div className="commitment-list">{fixedRows.map(e => <div className="commitment" key={e.id}><IconCategory category={e.category} /><div><strong>{e.name}</strong><span>{e.category} · {frequencyLabels[e.frequency || 'monthly']}</span></div><strong>{currency(monthlyAmount(e))}<small className="movement-equivalent">{money(originalMonthlyAmount(e), originalCurrency(e))} {originalCurrency(e)}</small></strong><button className="icon-button" aria-label={`Editar ${e.name}`} onClick={() => editMovement('expense', e)}><Pencil size={15} /></button></div>)}{!fixedRows.length && <Empty icon={<Wallet size={24} />} title="Un presupuesto a tu medida" text="Registra lo que debes pagar cada mes." action={() => setModal({ type: 'movement', kind: 'expense' })} label="Añadir compromiso" />}</div><div className="commitment-total"><span>Total mensual reservado</span><strong>{currency(summary.fixedExpenses)}</strong></div></section><div><section className="panel savings-budget"><span className="large-soft-icon"><PiggyBank size={25} /></span><h2>Un lugar para tu futuro</h2><p>Reserva una parte de tus ingresos. Tú decides cuánto, incluso si este mes es cero.</p><form onSubmit={e => { e.preventDefault(); const val = Number(new FormData(e.currentTarget).get('savings')); if (Number.isFinite(val) && val >= 0) { setData(d => ({ ...d, savingsAmount: val, savingsCurrency: prefs.currency, savingsExchangeRate: snapshotCopy(exchangeRates.snapshot) })); setToast('Tu reserva de ahorro se actualizó.'); } }}><label>Ahorro mensual ({prefs.currency})<div className="money-field"><span>{prefs.currency}</span><input key={`${prefs.currency}-${data.savingsAmount}-${summary.savings}`} name="savings" type="number" min="0" step="0.01" defaultValue={summary.savings ?? ''} placeholder={summary.savings === null ? 'Sin tasa' : '0.00'} required /></div></label><button className="primary-button" type="submit">Actualizar ahorro <Check size={15} /></button></form><p className="fx-summary-note">Reserva guardada: {money(data.savingsAmount, savingsCurrency)} {savingsCurrency}. {summary.savings === null ? 'Su equivalencia está pendiente. Puedes configurar tasas o definir una nueva reserva.' : 'El campo muestra su equivalente en la moneda del resumen.'} Solo «Actualizar ahorro» cambia el importe y su moneda.</p><small>La reserva se aplica a todos los meses; cambiarla recalcula los informes. Las metas sirven para hacer seguimiento; no se descuentan dos veces.</small></section><div className="budget-note"><Sparkles size={19} /><p><strong>Tu presupuesto es flexible.</strong> Después de compromisos y ahorro, tienes {currency(summary.freeBudget)} para tus gastos variables. Ya utilizaste {currency(summary.variableExpenses)}.</p></div></div></div>}
        {page === 'goals' && <><div className="goals-summary"><div><span className="large-soft-icon"><Target size={27} /></span><div><span>Lo que ya has construido</span><strong>{currency(goalSavedTotal)}</strong></div></div><p>Cada aporte cuenta.<br /><strong>{data.goals.length} metas</strong> con un propósito.</p></div><GoalsPanel full /><div className="info-note"><CircleHelp size={17} />El progreso de tus metas se actualiza manualmente. La reserva mensual de ahorro se configura en Mi presupuesto y se descuenta una sola vez.</div></>}
        {page === 'reports' && <><section className="panel trend-panel"><div className="panel-header"><div><h2>Tu camino financiero</h2><p>Ingresos y gastos durante los últimos seis meses.</p></div><div className="trend-legend"><span><i style={{ background: '#087f46' }} />Ingresos</span><span><i style={{ background: '#7fba99' }} />Gastos</span></div></div><div className="trend-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend} margin={{ left: 5, right: 25, top: 20, bottom: 5 }}><defs><linearGradient id="incomeGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#087f46" stopOpacity={0.18} /><stop offset="100%" stopColor="#087f46" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#dcebe2" /><XAxis dataKey="label" tick={{ fontSize: 12 }} axisLine={false} tickLine={false} /><YAxis tick={{ fontSize: 11 }} axisLine={false} tickLine={false} /><Tooltip formatter={tooltipMoney} contentStyle={tooltipStyle} /><Area isAnimationActive={false} type="monotone" dataKey="income" name="Ingresos" stroke="#087f46" strokeWidth={2} fill="url(#incomeGradient)" /><Area isAnimationActive={false} type="monotone" dataKey="expenses" name="Gastos" stroke="#7fba99" strokeWidth={2} fill="transparent" /></AreaChart></ResponsiveContainer></div></section><div className="export-cards">{([{ format: 'xlsx', icon: FileSpreadsheet, title: 'Tus datos, a tu manera', text: 'Todos los movimientos del mes en una hoja de cálculo.', label: 'Descargar Excel' }, { format: 'pdf', icon: FileBarChart2, title: 'El panorama completo', text: 'Un informe con tu resumen financiero y movimientos.', label: 'Descargar PDF' }, { format: 'docx', icon: FileText, title: 'Dale tu propio enfoque', text: 'Un informe editable para añadir tus notas y planes.', label: 'Descargar Word' }] as const).map(c => <section className="panel export-card" key={c.format}><span className="large-soft-icon"><c.icon size={24} /></span><h2>{c.title}</h2><p>{c.text}</p><button className="outline-button" disabled={busy} onClick={() => download(c.format)}><Download size={15} />{c.label}</button></section>)}</div></>}
        <footer className="page-footer"><span><ShieldCheck size={13} />Tus datos se quedan contigo, en este navegador.</span><span>Un poco más de claridad. Cada día. <span className="footer-brand">KONTEN.</span></span></footer>
      </main>
    </div>
    {toast && <div className="toast" role="status"><span><Check size={16} /></span>{toast}<button aria-label="Cerrar aviso" onClick={() => setToast('')}><X size={15} /></button></div>}
    {modal && <Modal title={modal.type === 'movement' ? modal.item ? 'Editar movimiento' : 'Un nuevo movimiento' : modal.type === 'goal' ? modal.item ? 'Tu meta, a tu ritmo' : 'Todo empieza con una meta' : modal.type === 'customize' ? 'Tu espacio, a tu manera' : modal.type === 'settings' ? 'Tu espacio personal' : 'Un poco de ayuda'} onClose={() => setModal(null)}>
      {modal.type === 'movement' && <MovementForm kind={modal.kind} item={modal.item} fixed={modal.fixed} month={month} currency={prefs.currency} rates={exchangeRates.snapshot} onSave={(kind, item) => { setData(d => kind === 'income' ? { ...d, incomes: [...d.incomes.filter(i => i.id !== item.id), item as Income] } : { ...d, expenses: [...d.expenses.filter(e => e.id !== item.id), item as Expense] }); setModal(null); setToast(convertAmount(item.amount, entryCurrency(item), prefs.currency, resolveEntryRate(item, conversion)) === null ? 'Movimiento guardado en su moneda original. Equivalencia pendiente: configura el tipo de cambio.' : modal.item ? 'Movimiento actualizado. Tu resumen ya está al día.' : 'Movimiento añadido. Cada peso cuenta.'); }} />}
      {modal.type === 'goal' && <GoalForm item={modal.item} currency={prefs.currency} rates={exchangeRates.snapshot} onDelete={id => { if (window.confirm('¿Eliminar esta meta de ahorro?')) { setData(d => ({ ...d, goals: d.goals.filter(g => g.id !== id) })); setModal(null); setToast('Meta eliminada.'); } }} onSave={goal => { setData(d => ({ ...d, goals: [...d.goals.filter(g => g.id !== goal.id), goal] })); setModal(null); setToast('Tu meta se guardó. Un paso más cerca.'); }} />}
      {modal.type === 'customize' && <div className="customize-form"><p>Elige la información que te ayuda a tomar mejores decisiones.</p><h3>Tarjetas del resumen</h3>{stats.map(s => <label className="checkbox-row" key={s.id}><span><s.icon size={19} />{s.label}</span><input type="checkbox" checked={prefs.cards.includes(s.id)} onChange={e => updatePrefs({ cards: e.target.checked ? [...prefs.cards, s.id] : prefs.cards.filter((id: string) => id !== s.id) })} /></label>)}<h3>Orden de las tarjetas visibles</h3><div className="card-order">{prefs.cards.map((id: string, index: number) => <div key={id}><span>{stats.find(s => s.id === id)?.label}</span><button disabled={index === 0} aria-label={`Mover ${stats.find(s => s.id === id)?.label} antes`} onClick={() => { const cards = [...prefs.cards]; [cards[index - 1], cards[index]] = [cards[index], cards[index - 1]]; updatePrefs({ cards }); }}><ChevronLeft size={16} /></button><button disabled={index === prefs.cards.length - 1} aria-label={`Mover ${stats.find(s => s.id === id)?.label} después`} onClick={() => { const cards = [...prefs.cards]; [cards[index + 1], cards[index]] = [cards[index], cards[index + 1]]; updatePrefs({ cards }); }}><ChevronRight size={16} /></button></div>)}</div><h3>Tu gráfica favorita</h3><div className="chart-choice">{(['pie', 'bar', 'scatter'] as ChartType[]).map((c, i) => <button className={prefs.chart === c ? 'active' : ''} key={c} onClick={() => updatePrefs({ chart: c })}>{['Pastel', 'Barras', 'Puntos'][i]}</button>)}</div><h3>Secciones adicionales</h3><label className="checkbox-row"><span><ArrowLeftRight size={19} />Últimos movimientos</span><input type="checkbox" checked={prefs.showTransactions} onChange={e => updatePrefs({ showTransactions: e.target.checked })} /></label><label className="checkbox-row"><span><Target size={19} />Metas de ahorro</span><input type="checkbox" checked={prefs.showGoals} onChange={e => updatePrefs({ showGoals: e.target.checked })} /></label><button className="primary-button full-width" onClick={() => { setModal(null); setToast('Listo. Esta vista es muy tuya.'); }}>Guardar mi vista <Check size={16} /></button></div>}
      {modal.type === 'settings' && <div className="settings-form"><CloudAccountPanel state={cloud} /><InstallAppPanel state={installApp} /><p>{cloud.isCloud ? 'Los cambios se guardan en este dispositivo y se envían a tu cuenta cuando hay conexión. Conservá también un respaldo completo.' : 'Tu información se guarda automáticamente en este navegador. Entrá a tu cuenta para compartirla entre dispositivos.'}</p>
        <fieldset className="cloud-finance-controls" disabled={accountGate}>{data.legacyCurrencyReview && <LegacyCurrencyReview previous={data.legacyCurrencyReview} onConfirm={code => { setData(previous => { const { legacyCurrencyReview: _review, ...original } = previous; return migrateCurrency(original, code); }); setToast('Moneda original confirmada. Se conservaron todos los importes.'); }} />}
        <label>Moneda del resumen<select aria-label="Moneda del resumen en ajustes" value={prefs.currency} onChange={e => isCurrency(e.target.value) && updatePrefs({ currency: e.target.value })}><CurrencyOptions /></select></label>
        <div className="info-note">Puedes cambiar la moneda del resumen sin alterar tus registros. Cada ingreso, gasto, reserva y meta conserva su moneda original.</div>
        <ExchangeRatesPanel state={exchangeRates} onRateTypeChange={rateType => updatePrefs({ rateType })} /></fieldset><DataBackupPanel data={data} preferences={prefs} cloud={cloud.isCloud} disabled={Boolean(cloud.email && (!cloud.isCloud || cloud.readOnly))} onRestore={cloud.isCloud ? backup => { restoreBackupRateCaches(backup, localStorage); window.dispatchEvent(new Event('konten:rates-restored')); setData(backup.data); setPrefs({ ...defaultPrefs, ...backup.preferences, demo: false }); setToast('Respaldo cargado. Revisá el estado de sincronización antes de cerrar KONTEN.'); } : undefined} />
        <div className="info-note">La referencia elegida se guarda con los movimientos nuevos. Los registros sin tasa usan la referencia actual; las tasas ya guardadas se conservan aunque actualices BAC o cambies entre compra y venta. Puedes actualizar una tasa al editar el movimiento.</div>
        <div className="local-settings"><ShieldCheck size={23} /><div><strong>Un espacio privado</strong><p>{cloud.isCloud ? 'Tus registros se comparten únicamente con tu cuenta privada. Las consultas públicas de BAC no incluyen tus movimientos. Conservá un respaldo y comprobá que no queden cambios pendientes antes de borrar datos del navegador.' : 'Sin una cuenta conectada, tus registros se guardan en este navegador. Las consultas de BAC no incluyen tus movimientos. Si borrás los datos del navegador, perderás los registros locales.'}</p></div></div><button className="outline-button full-width" onClick={() => download('xlsx')}><Download size={16} />Exportar movimientos de este mes</button><button className="danger-button" disabled={Boolean(cloud.email && (!cloud.isCloud || cloud.readOnly))} onClick={() => { if (window.confirm(cloud.isCloud ? '¿Eliminar todos los registros de tu cuenta? Al sincronizar también se eliminarán en tus otros dispositivos. Descargá un respaldo completo antes de continuar.' : '¿Eliminar todos los datos y comenzar desde cero? Esta acción no se puede deshacer. Exporta tus datos antes de continuar.')) { setData({ incomes: [], expenses: [], goals: [], savingsAmount: 0, legacyCurrency: prefs.currency, savingsCurrency: prefs.currency }); updatePrefs({ demo: false }); setModal(null); setToast('Tu espacio está listo para empezar de cero.'); } }}>Borrar datos y comenzar de cero</button><small>Al iniciar por primera vez mostramos datos de ejemplo para que explores KONTEN.</small></div>}
      {modal.type === 'help' && <div className="help-content"><p>Más claridad, una decisión a la vez.</p><div><span>01</span><section><h3>Empieza por lo que recibes</h3><p>Registra tu salario como ingreso mensual automático. Si cobras quincenalmente, introduce el importe de cada quincena: contamos dos pagos al mes. Usa «Ingreso puntual» para un trabajo extra o una devolución.</p></section></div><div><span>02</span><section><h3>Dale un lugar a tus compromisos</h3><p>Los gastos fijos se descuentan cada mes desde su fecha de inicio. Los variables solo afectan el mes de su fecha. Un importe quincenal equivale a dos pagos mensuales.</p></section></div><div><span>03</span><section><h3>Haz espacio para el futuro</h3><p>Reserva ahorro en Mi presupuesto. Tu disponible es el ingreso menos gastos fijos, variables y ahorro. No necesitas fijar ahorro para empezar.</p></section></div><div className="info-note">KONTEN es una herramienta de organización personal. Los pagos y las transferencias no se ejecutan en tu banco.</div></div>}
    </Modal>}
  </div>;
}
const tooltipStyle = { border: '1px solid #dcebe2', borderRadius: 10, fontSize: 12, boxShadow: '0 5px 20px #163d2812' };
function Empty({ icon, title, text, action, label }: { icon: ReactNode; title: string; text: string; action?: () => void; label?: string }) { return <div className="empty-state"><span>{icon}</span><h3>{title}</h3><p>{text}</p>{action && <button className="text-button" onClick={action}>{label} <ArrowRight size={14} /></button>}</div>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { const last = document.activeElement as HTMLElement; const old = document.body.style.overflow; document.body.style.overflow = 'hidden'; const first = ref.current?.querySelector<HTMLElement>('button, input, select'); first?.focus(); function trap(e: KeyboardEvent) { if (e.key !== 'Tab') return; const els = ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input, select, textarea, [tabindex="0"]'); if (!els?.length) return; if (e.shiftKey && document.activeElement === els[0]) { e.preventDefault(); els[els.length - 1].focus(); } else if (!e.shiftKey && document.activeElement === els[els.length - 1]) { e.preventDefault(); els[0].focus(); } } document.addEventListener('keydown', trap); return () => { document.body.style.overflow = old; document.removeEventListener('keydown', trap); last?.focus(); }; }, []);
  return <div className="modal-overlay" onMouseDown={e => e.target === e.currentTarget && onClose()}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><div className="modal-header"><div><span className="eyebrow">UN POCO MÁS DE CLARIDAD</span><h2 id="modal-title">{title}</h2></div><button className="icon-button" aria-label="Cerrar ventana" onClick={onClose}><X size={20} /></button></div>{children}</div></div>;
}
function LegacyCurrencyReview({ previous, onConfirm }: { previous: string; onConfirm: (currency: Currency) => void }) {
  const [selected, setSelected] = useState<Currency | ''>('');
  return <section className="fx-legacy-review"><h3>Revisar moneda de los registros anteriores</h3><p>La versión anterior mostraba {previous} sin convertir importes. Esa moneda aún no tiene conversión aquí. Elige USD, NIO o EUR solo si corresponde a la moneda real de esos importes. Si eran {previous}, conserva una exportación y revisa los registros antes de continuar.</p><label>Moneda real de los registros anteriores<select value={selected} onChange={event => isCurrency(event.target.value) && setSelected(event.target.value)}><option value="" disabled>Selecciona la moneda real</option><CurrencyOptions /></select></label><button className="outline-button" type="button" disabled={!selected} onClick={() => { if (selected && window.confirm(`¿Confirmas que los importes anteriores estaban expresados en ${selected}? Se conservarán los números, sin convertirlos desde ${previous}.`)) onConfirm(selected); }}>Confirmar moneda original</button></section>;
}
function MovementForm({ kind: initialKind, item, fixed = false, month, currency, rates, onSave }: { kind: 'income' | 'expense'; item?: Income | Expense; fixed?: boolean; month: string; currency: Currency; rates: CurrencyRateSnapshot | null; onSave: (kind: 'income' | 'expense', item: Income | Expense) => void }) {
  const [kind, setKind] = useState(initialKind);
  const [source, setSource] = useState(item?.category || (kind === 'income' ? 'Salario' : 'Vivienda'));
  const [frequency, setFrequency] = useState<Income['frequency']>(item && 'frequency' in item && item.frequency ? item.frequency : 'monthly');
  const [expenseKind, setExpenseKind] = useState<Expense['kind']>(item && 'kind' in item ? item.kind : fixed ? 'fixed' : 'variable');
  const [name, setName] = useState(item?.name || '');
  const [amountText, setAmountText] = useState(item ? String(item.amount) : '');
  const [movementCurrency, setMovementCurrency] = useState<Currency>(item && isCurrency(item.currency) ? item.currency : currency);
  const [useCurrent, setUseCurrent] = useState(false);
  const capturedRate = item && isValidRateSnapshot(item.exchangeRate) && entryCurrency(item) === movementCurrency ? item.exchangeRate : null;
  const selectedRate = capturedRate && !(useCurrent && isValidRateSnapshot(rates)) ? capturedRate : rates;
  const amount = Number(amountText);
  const equivalent = amountText && Number.isFinite(amount) ? convertAmount(amount, movementCurrency, currency, selectedRate) : null;
  const defaultDate = month === currentMonth ? today : `${month}-01`;
  const incomeSources = ['Salario', 'Trabajo independiente', 'Negocio', 'Inversiones', 'Devolución de préstamo', 'Regalo', 'Otro ingreso'];
  return <form className="movement-form" onSubmit={event => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    if (!Number.isFinite(amount) || amount <= 0) return;
    const base = { id: item?.id || crypto.randomUUID(), name: name.trim(), category: source, amount, currency: movementCurrency, exchangeRate: snapshotCopy(selectedRate), date: String(form.get('date')) };
    if (!base.name) return;
    onSave(kind, kind === 'income' ? { ...base, frequency } : { ...base, kind: expenseKind, frequency: expenseKind === 'fixed' ? frequency === 'once' ? 'monthly' : frequency : 'once' });
  }}>
    {!item && <div className="movement-kind-toggle"><button type="button" className={kind === 'expense' ? 'active' : ''} onClick={() => { setKind('expense'); setSource('Vivienda'); }}><ArrowUpRight size={17} />Gasto</button><button type="button" className={kind === 'income' ? 'active' : ''} onClick={() => { setKind('income'); setSource('Salario'); setFrequency('monthly'); }}><ArrowDownLeft size={17} />Ingreso</button></div>}
    <label>Moneda del movimiento<select value={movementCurrency} onChange={event => isCurrency(event.target.value) && setMovementCurrency(event.target.value)}><CurrencyOptions /></select></label>
    <div className="form-row"><label>{kind === 'income' ? 'Fuente de ingreso' : 'Clasificación'}<select value={source} onChange={event => { setSource(event.target.value); if (kind === 'income' && event.target.value === 'Salario') setFrequency('monthly'); if (kind === 'income' && ['Regalo', 'Devolución de préstamo'].includes(event.target.value)) setFrequency('once'); }}>{(kind === 'income' ? incomeSources : categories).map(category => <option key={category}>{category}</option>)}</select></label><label>Monto ({movementCurrency})<input name="amount" type="number" min="0.01" max="999999999" step="0.01" placeholder="0.00" value={amountText} onChange={event => setAmountText(event.target.value)} required /></label></div>
    <div className="fx-conversion-preview" aria-live="polite"><strong>Equivalente por pago en {currency}: {amountText ? money(equivalent, currency) : '—'}</strong><span>{movementCurrency === currency ? 'La moneda coincide con la del resumen.' : equivalent === null ? 'Puedes guardar el importe original. Su equivalencia quedará pendiente hasta configurar el tipo de cambio.' : rateDescription(selectedRate)}</span>{capturedRate && !(useCurrent && isValidRateSnapshot(rates)) && <span>Se conserva la referencia guardada con este movimiento.</span>}</div>
    {capturedRate && <label className="checkbox-row"><span>Usar la referencia actual para este movimiento</span><input type="checkbox" checked={useCurrent} disabled={!isValidRateSnapshot(rates)} onChange={event => setUseCurrent(event.target.checked)} /></label>}
    {capturedRate && useCurrent && rates && <p className="fx-summary-note">Al guardar se reemplazará la tasa anterior por {rateDescription(rates)}. Esto recalcula la equivalencia de su recurrencia.</p>}
    <label>Concepto<input value={name} onChange={event => setName(event.target.value)} pattern=".*\S.*" title="Escribe un concepto con al menos un carácter visible" maxLength={80} required placeholder={kind === 'income' ? 'Ej. Salario de mi trabajo' : 'Ej. Renta del apartamento'} /></label>
    {kind === 'expense' && <fieldset><legend>¿Cómo es este gasto?</legend><div className="expense-kind-cards"><label className={expenseKind === 'fixed' ? 'active' : ''}><input type="radio" name="expenseKind" checked={expenseKind === 'fixed'} onChange={() => { setExpenseKind('fixed'); if (frequency === 'once') setFrequency('monthly'); }} /><span><strong>Fijo</strong><small>Un compromiso recurrente</small></span><Wallet size={18} /></label><label className={expenseKind === 'variable' ? 'active' : ''}><input type="radio" name="expenseKind" checked={expenseKind === 'variable'} onChange={() => setExpenseKind('variable')} /><span><strong>Variable</strong><small>Un gasto de este momento</small></span><ShoppingBag size={18} /></label></div></fieldset>}
    <div className="form-row">{(kind === 'income' || expenseKind === 'fixed') && <label>Periodicidad<select value={frequency} onChange={event => setFrequency(event.target.value as Income['frequency'])}><option value="monthly">Mensual</option><option value="biweekly">Quincenal (dos veces al mes)</option>{kind === 'income' && <option value="once">Ingreso puntual (una sola vez)</option>}</select></label>}<label>{kind === 'income' && frequency !== 'once' || kind === 'expense' && expenseKind === 'fixed' ? 'Fecha de inicio' : 'Fecha'}<input name="date" type="date" defaultValue={item?.date || defaultDate} required /></label></div>
    <div className="info-note"><Sparkles size={17} /><span>{kind === 'income' ? frequency === 'once' ? 'Este ingreso solo se sumará al mes de su fecha.' : frequency === 'biweekly' ? 'Introduce el importe por quincena. Se sumará dos veces cada mes, desde el mes de inicio.' : 'Este ingreso se sumará automáticamente cada mes, desde el mes de inicio.' : expenseKind === 'fixed' ? frequency === 'biweekly' ? 'Introduce el importe por quincena. Se descontará dos veces al mes.' : 'Este gasto se reservará automáticamente cada mes, desde el mes de inicio.' : 'Este gasto se descontará del disponible del mes seleccionado.'}</span></div>
    {item && recurrenceNotice(item) && <div className="info-note">Editar una recurrencia recalcula todos los meses desde su fecha de inicio.</div>}<button className="primary-button full-width" type="submit">{item ? 'Guardar cambios' : kind === 'income' ? 'Añadir ingreso' : 'Añadir gasto'}<ArrowRight size={17} /></button>
  </form>;
}
function recurrenceNotice(item: Income | Expense) { return 'kind' in item ? item.kind === 'fixed' : item.frequency !== 'once'; }
function GoalForm({ item, currency, rates, onSave, onDelete }: { item?: SavingsGoal; currency: Currency; rates: CurrencyRateSnapshot | null; onSave: (goal: SavingsGoal) => void; onDelete: (id: string) => void }) {
  const [goalCurrency, setGoalCurrency] = useState<Currency>(item && isCurrency(item.currency) ? item.currency : currency);
  return <form className="movement-form" onSubmit={event => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const target = Number(form.get('target')), saved = Number(form.get('saved')), monthly = Number(form.get('monthly'));
    const name = String(form.get('name')).trim();
    if (!name || ![target, saved, monthly].every(Number.isFinite) || target <= 0 || saved < 0 || monthly < 0) return;
    const snapshot = item && entryCurrency(item) === goalCurrency && isValidRateSnapshot(item.exchangeRate) ? item.exchangeRate : rates;
    onSave({ ...item, id: item?.id || crypto.randomUUID(), name, target, saved, monthly, currency: goalCurrency, exchangeRate: snapshotCopy(snapshot) });
  }}><p>Un viaje, una casa o esa tranquilidad que buscas. Ponle nombre.</p><label>Nombre de la meta<input name="name" defaultValue={item?.name} placeholder="Ej. Mi próximo viaje" pattern=".*\S.*" title="Escribe un nombre para tu meta" maxLength={60} required /></label><label>Moneda de la meta<select value={goalCurrency} onChange={event => isCurrency(event.target.value) && setGoalCurrency(event.target.value)}><CurrencyOptions /></select></label><div className="form-row"><label>Quiero alcanzar ({goalCurrency})<input type="number" name="target" defaultValue={item?.target} placeholder="3,000.00" min="0.01" step="0.01" required /></label><label>Ya tengo ahorrado ({goalCurrency})<input type="number" name="saved" defaultValue={item?.saved || 0} min="0" step="0.01" required /></label></div><label>Aporte mensual sugerido ({goalCurrency})<input type="number" name="monthly" defaultValue={item?.monthly || 0} min="0" step="0.01" required /></label><div className="info-note"><CircleHelp size={17} />Tu meta conserva sus importes en {goalCurrency} aunque cambies la moneda del resumen. Este aporte sugerido no se descuenta automáticamente del presupuesto.</div><button type="submit" className="primary-button full-width">Guardar mi meta <Target size={17} /></button>{item && <button className="danger-button" type="button" onClick={() => onDelete(item.id)}><Trash2 size={15} />Eliminar meta</button>}</form>;
}
export default App;
